let engine,q,range='all',scope='all',raceRange='all',ppgRange='since2020',hidden=new Set(),actions=new Map(),sequence=0,records=[],facts=[],lastReceipt=null,rot=0;
const names=id=>engine.data.franchises.find(f=>f.id===id),N=id=>E(names(id)?.displayName||names(id)?.currentName||id),year=y=>y===2026?'2026 YTD':`${y}${engine.data.seasons.some(s=>s.year===y&&s.status!=='complete')?' PARTIAL':''}`,wlt=r=>`${r.wins}–${r.losses}${r.ties?`–${r.ties}`:''}`,col=id=>colors[engine.data.franchises.findIndex(f=>f.id===id)%colors.length];
const selectedLabel=()=>range==='all'?'ALL IMPORTED HISTORY':range==='since2020'?'SINCE 2020':range==='since2021'?'2021–PRESENT':year(+range),scoringCoverage=r=>{const ys=[...new Set(r.scores.map(s=>s.season))];return ys.length?ys.map(year).join(', ')+' · '+r.scores.length+' regular-season franchise-weeks':'No imported scoring data in this range';},gameCoverage=r=>{const ys=[...new Set(r.games.map(s=>s.season))];return ys.length?ys.map(year).join(', ')+' · '+r.games.length+' known matchups':'No known matchups in this range';};
