function rivalryFile(a,b){const r=engine.rivalry(q,a,b);if(!r.games){showReceipt('RIVALRY FILE',pending('No verified meetings between these franchises in the selected range.'));return;}const gs=r.meetings;showReceipt('RIVALRY FILE · '+(names(a).displayName||names(a).currentName)+' vs '+(names(b).displayName||names(b).currentName),`<div class="mini-ledger">${[['Known record',wlt(r)],['Regular season',wlt(r.regular)],['Playoffs incl. third place',wlt(r.playoffs)],['PF',F(r.pf)],['PA',F(r.pa)],['Point differential',sign(r.diff)],['Average score',F(r.averageScore)],['Average margin',sign(r.averageMargin)],['Longest winning streak',r.streak.longestWin],['Current streak',r.streak.current?`${r.streak.current.count}${r.streak.current.outcome}`:'—']].map(([k,v])=>`<div><b>${v}</b><small>${k}</small></div>`).join('')}</div>${table(['FILE NOTE','VALUE','RECEIPT'],[['Largest victory',r.largestWin?F(r.largestWin.margin):'None',r.largestWin?`${year(r.largestWin.season)} W${r.largestWin.week}`:'—'],['Largest defeat',r.largestLoss?F(Math.abs(r.largestLoss.margin)):'None',r.largestLoss?`${year(r.largestLoss.season)} W${r.largestLoss.week}`:'—'],['Closest game',F(Math.abs(r.closest.margin)),`${year(r.closest.season)} W${r.closest.week}`],['Highest scoring meeting',F(r.highest.pf+r.highest.pa),`${year(r.highest.season)} W${r.highest.week}`],['Lowest scoring meeting',F(r.lowest.pf+r.lowest.pa),`${year(r.lowest.season)} W${r.lowest.week}`],['Most recent meeting',`${F(r.latest.pf)} – ${F(r.latest.pa)}`,`${year(r.latest.season)} W${r.latest.week}`]])}<h3>Every known meeting · chronological</h3><p class="note">Historical team names are preserved below. Missing meetings are not reconstructed. Streaks span consecutive known meetings and may be interrupted by missing history.</p>`,gs,'rivalry:'+a+':'+b);}
function rivalryCard(r,even=false){return `<article class="rival-card"><span class="stamp">${even?'UNCOMFORTABLY CLOSE':r.winPct===1?'CERTIFIED OWNERSHIP':r.winPct>=.75?'RENT FREE':'FAVORABLE'}</span><h3>${N(r.franchise)}<br>vs ${N(r.opponent)}</h3><b class="giant">${wlt(r)}</b><p>${P(r.winPct)} wins · ${sign(r.diff)} total differential<br>${sign(r.averageMargin)} average margin · largest win ${r.largestWin?F(r.largestWin.margin):'none'}<br>Current: ${r.streak.current.count}${r.streak.current.outcome}</p><button class="receipt-btn" ${action(()=>rivalryFile(r.franchise,r.opponent))}>OPEN THE RIVALRY FILE ↗</button></article>`;}
function personality(franchise){const rows=q.orientedPairs.filter(p=>p.franchise===franchise).sort((a,b)=>b.winPct-a.winPct||b.averageMargin-a.averageMargin);if(!rows.length)return pending('No known opponents in this range.');const qual=rows.filter(r=>r.games>=3),victim=qual[0],hell=qual.at(-1);return `<div class="split-grid"><article><span class="eyebrow">FAVORITE VICTIM / WHO YOU OWN</span><h3>${victim?N(victim.opponent):'Sample too small.'}</h3><p>${victim?`${wlt(victim)} · ${sign(victim.diff)} points`: 'At least three meetings per opponent before applying ownership labels.'}</p></article><article><span class="eyebrow">PERSONAL HELL / WHO OWNS YOU</span><h3>${hell?N(hell.opponent):'No nemesis on file.'}</h3><p>${hell?`${wlt(hell)} · ${sign(hell.diff)} points`:'Single meetings are evidence, not a lifetime curse.'}</p></article></div>${table(['OPPONENT','W–L–T','WIN %','PF','PA','DIFF','AVG MARGIN','VERDICT'],rows.map(r=>[`<button class="receipt-btn" ${action(()=>rivalryFile(franchise,r.opponent))}>${N(r.opponent)}</button>`,wlt(r),P(r.winPct),F(r.pf),F(r.pa),sign(r.diff),sign(r.averageMargin),r.games<3?'SMALL SAMPLE':r.winPct>=.75?'FAVORABLE':r.winPct<=.25?'PROPERTY OF '+N(r.opponent):r.winPct>.5?'FAVORABLE':r.winPct<.5?'PROBLEM':'EVEN']))}`;}
