 html+=sec(28,'record-book',"THE FUCKIN’ RECORD BOOK",`<div class="control-row"><label for="record-search">Search the evidence</label><input id="record-search" type="search" placeholder="Team, record, or category…"><label for="record-category">Category</label><select id="record-category"><option>ALL</option>${['CAREER','SEASON','GAME','RIVALRY','STREAKS'].map(c=>`<option>${c}</option>`).join('')}</select></div><div id="record-results"></div><p class="note">Unsupported title droughts, final finishes and qualified season records remain absent until their evidence or minimum sample is available. Partial-season records are always marked.</p>`);
