function championshipSummary(){const complete=q.seasons.filter(s=>s.status==='complete'),verified=complete.every(s=>s.championshipsVerified&&q.champs.some(c=>c.season===s.year)),ys=complete.map(s=>s.year).sort((a,b)=>a-b),contiguous=ys.every((y,i)=>!i||y===ys[i-1]+1);const rows=q.career.map(c=>{const wins=q.champs.filter(t=>t.champion===c.franchise),last=sorted(wins,'season')[0];let longest=0,run=0;for(const y of ys){if(wins.some(w=>w.season===y))run=0;else run++;longest=Math.max(longest,run);}return [receipt(N(c.franchise),'CHAMPIONSHIP HISTORY',c.championshipEvidence),c.titles,c.titles+c.runners,c.runners,verified&&contiguous?longest:'Coverage incomplete',verified&&contiguous&&last?ys.at(-1)-last.season:'Unknown'];});return table(['FRANCHISE','TITLES','FINAL APPEARANCES','RUNNER-UPS','LONGEST OBSERVED DROUGHT','COMPLETED YEARS SINCE LAST TITLE'],rows)+'<p class="note">Droughts exclude 2026 YTD and need contiguous, verified championship seasons. A franchise with no known title has an unknown last-title date.</p>';}
function eraBook(a,b,label){const ss=q.scores.filter(s=>s.season>=a&&s.season<=b),gs=q.games.filter(s=>s.season>=a&&s.season<=b),cs=q.champs.filter(s=>s.season>=a&&s.season<=b),rows=engine.data.franchises.map(f=>{const s=ss.filter(s=>s.franchise===f.id),g=gs.filter(g=>g.teamA===f.id||g.teamB===f.id).map(g=>H.side(g,f.id));return {franchise:f.id,pf:H.sum(s,'score'),ppg:s.length?H.sum(s,'score')/s.length:null,wins:g.filter(g=>g.margin>0).length,highs:q.belt.crowns.find(c=>c.franchise===f.id).highEvidence.filter(s=>s.season>=a&&s.season<=b).length,titles:cs.filter(c=>c.champion===f.id).length,evidence:s,games:g};}).filter(r=>r.evidence.length||cs.some(c=>c.champion===r.franchise)||r.games.length);return `<article class="era-book"><h3>${E(label)}<small>${a}–${b===2026?'today':b}</small></h3>${rows.length?['pf','ppg','highs','wins','titles'].map((k,i)=>{const lead=leader(rows,k);return `<p><b>${['POINTS','PPG','WEEKLY CROWNS','KNOWN WINS','VERIFIED TITLES'][i]}</b><br>${['pf','ppg','highs'].includes(k)&&!ss.length?'Weekly scoring unavailable':k==='titles'&&!cs.length?'Awaiting championship import':k==='wins'&&!gs.length?'Known matchups unavailable':receipt(lead.map(r=>N(r.franchise)).join(' / ')+' · '+(k==='pf'||k==='ppg'?F(lead[0][k]):lead[0][k]),'ERA LEADER',lead.flatMap(r=>k==='wins'?r.games:k==='titles'?cs.filter(c=>c.champion===r.franchise):r.evidence))}</p>`;}).join('')+`<small class="note">Observed years only: ${[...new Set(ss.map(s=>s.season))].map(year).join(', ')}</small>`:pending('This era has no imported scoring history in the selected range.')}</article>`;}
function chart(series,xs,kind){if(!xs.length)return pending('No scoring observations in this window.');let visible=series.filter(s=>s.franchise==='league'||!hidden.has(s.franchise)),values=visible.flatMap(s=>s.points.map(p=>p.value)),max=Math.max(1,...values)*1.08,W=Math.min(950,Math.max(320,($('#race-chart')?.clientWidth||innerWidth)-34)),HH=320,L=65,R=25,T=20,B=50,x=i=>L+(xs.length===1?(W-L-R)/2:i/(xs.length-1)*(W-L-R)),y=v=>HH-B-v/max*(HH-T-B);let svg=`<svg class="history-chart" viewBox="0 0 ${W} ${HH}" role="img" aria-label="${kind==='race'?'Cumulative points by week':'Season points per game'}"><title>${kind==='race'?'Cumulative observed scoring race':'Season average points per recorded week'}</title>`;for(let i=0;i<=4;i++){let val=max*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(val)}" y2="${y(val)}" stroke="#c7beaa" stroke-width=".7"/><text x="${L-10}" y="${y(val)+4}" text-anchor="end">${Math.round(val).toLocaleString('en-US')}</text>`;}
 xs.forEach((xx,i)=>{if(xs.length>10&&i%Math.ceil(xs.length/8)&&i!==xs.length-1)return;svg+=`<text x="${x(i)}" y="${HH-20}" text-anchor="middle">${E(xx.label)}</text>`;});
 for(const s of visible){let pts=s.points.map(p=>({p,i:xs.findIndex(z=>z.key===p.key)})).filter(r=>r.i>=0);let color=s.franchise==='league'?'#333':col(s.franchise);svg+=`<polyline points="${pts.map(({p,i})=>x(i)+','+y(p.value)).join(' ')}" fill="none" stroke="${color}" stroke-width="${s.franchise==='league'?2:2.5}"${s.franchise==='league'?' stroke-dasharray="7 5"':''}/>`;for(const {p,i} of pts){let title=`${s.franchise==='league'?'LEAGUE AVERAGE':names(s.franchise).displayName||names(s.franchise).currentName} / ${year(p.season)}${p.week?' W'+p.week:''}: ${F(p.value)}${kind==='race'?' cumulative points':` PPG · ${p.games} scoring weeks · ${F(p.pf)} PF · rank ${p.rank||'league'}`}`;svg+=`<circle class="chart-point" cx="${x(i)}" cy="${y(p.value)}" r="4.5" fill="${color}" tabindex="0" role="button" aria-label="${E(title)}" data-chart-tip="${E(title)}" ${action(()=>showReceipt(kind==='race'?'SCORING RACE RECEIPT':'SEASON PPG RECEIPT',`<p>${E(title)}</p>`,(typeof p.evidence==='function'?p.evidence():p.evidence)))}><title>${E(title)}</title></circle>`;}}svg+='</svg>';return `<div class="chart-stage">${svg}<p class="chart-tooltip" aria-live="polite">Hover, focus, or tap a plotted observation. Click to open its receipts.</p></div>`;}
function subquery(sub){if(sub==='all')return q;let out=Object.create(q);out.scores=q.scores.filter(s=>s.season>=2020);out.seasonRows=q.seasonRows.filter(s=>s.season>=2020);out.leagueRows=q.leagueRows.filter(s=>s.season>=2020);return out;}
function drawRace(){const r=subquery(raceRange),keys=[...new Set(r.scores.map(s=>s.season+':'+s.week))].sort((a,b)=>{let [ay,aw]=a.split(':').map(Number),[by,bw]=b.split(':').map(Number);return ay-by||aw-bw;}),xs=keys.map(k=>{let [y,w]=k.split(':').map(Number);return {key:k,label:`${y===2026?'26 YTD':String(y).slice(2)} W${w}`};});const series=engine.data.franchises.map(f=>{let total=0,own=r.scores.filter(s=>s.franchise===f.id);let pts=own.map((s,i)=>{total+=Math.round(s.score*100);return {key:s.season+':'+s.week,season:s.season,week:s.week,value:total/100,evidence:()=>own.slice(0,i+1)};});return {franchise:f.id,points:pts};});$('#race-chart').innerHTML=chart(series,xs,'race');const totals=series.filter(s=>s.points.length).map(s=>({franchise:s.franchise,total:s.points.at(-1).value,evidence:s.points.at(-1).evidence()})).sort((a,b)=>b.total-a.total),max=totals[0]?.total||1;$('#race-bars').innerHTML=totals.map(r=>`<button class="chart-bar" style="--team-color:${col(r.franchise)}" ${action(()=>showReceipt('CUMULATIVE POINTS',`<p>${N(r.franchise)} · ${F(r.total)} imported points.</p>`,r.evidence))}>${N(r.franchise)}<span><i style="width:${r.total/max*100}%"></i></span><b>${F(r.total)}</b></button>`).join('');let races=[];for(let i=1;i<totals.length;i++)races.push({a:totals[i-1],b:totals[i],gap:totals[i-1].total-totals[i].total});races.sort((a,b)=>a.gap-b.gap);const close=races[0];$('#race-callout').innerHTML=close?`<div class="race-callout"><span class="eyebrow">CLOSEST IMPORTED SCORING RACE</span><h3>${close.gap<=10?'ONE FUCKING CATCH APART':'THE NARROWEST GAP ON FILE'}</h3><p>${N(close.a.franchise)} and ${N(close.b.franchise)}: ${F(close.a.total+close.b.total)} combined points across ${[...new Set(r.scores.map(s=>s.season))].length} observed season${new Set(r.scores.map(s=>s.season)).size===1?'':'s'}. Only ${F(close.gap)} separates them.</p>${receipt('OPEN BOTH SCORING LEDGERS ↗','CLOSEST CAREER SCORING RACE',[...close.a.evidence,...close.b.evidence])}</div>`:'';}
function drawYears(){const r=subquery(ppgRange),ys=[...new Set(r.seasonRows.map(s=>s.season))].sort((a,b)=>a-b),xs=ys.map(y=>({key:String(y),label:year(y)})),series=engine.data.franchises.map(f=>({franchise:f.id,points:r.seasonRows.filter(s=>s.franchise===f.id).map(s=>({...s,key:String(s.season),value:s.ppg}))}));series.push({franchise:'league',points:r.leagueRows.map(l=>({...l,key:String(l.season),value:l.ppg}))});$('#year-chart').innerHTML=chart(series,xs,'years');$('#year-legend').innerHTML=engine.data.franchises.map(f=>`<button class="team-toggle" style="--team-color:${col(f.id)}" data-toggle-team="${f.id}" aria-pressed="${!hidden.has(f.id)}"><i></i>${N(f.id)}</button>`).join('')+'<span class="team-toggle">— LEAGUE AVERAGE</span>';}
function buildFacts(){facts=[];const add=(title,text,rows)=>facts.push({title,text,rows});const top=sorted(q.scores,'score')[0],bottom=sorted(q.scores,'score',false)[0],m=q.meetings.filter(g=>g.winner),loss=sorted(m,'loseScore')[0],win=sorted(m,'winScore',false)[0],combined=sorted(q.meetings,'combined')[0],small=sorted(q.meetings,'combined',false)[0];if(top)add('The ceiling has a name.',`${names(top.franchise).displayName||names(top.franchise).currentName} put up ${F(top.score)} in ${year(top.season)}, Week ${top.week}. Highest supplied weekly score.`,[top]);if(bottom)add('The basement has a tenant.',`${names(bottom.franchise).displayName||names(bottom.franchise).currentName}: ${F(bottom.score)} in ${year(bottom.season)}, Week ${bottom.week}. Lowest supplied weekly score.`,[bottom]);if(loss)add('Great score. Shit receipt.',`${names(loss.loser).displayName||names(loss.loser).currentName} lost with ${F(loss.loseScore)}. ${names(loss.winner).displayName||names(loss.winner).currentName} had ${F(loss.winScore)}. ${year(loss.season)} W${loss.week}.`,[loss]);if(win)add('The minimum viable victory.',`${names(win.winner).displayName||names(win.winner).currentName} won with ${F(win.winScore)} in ${year(win.season)} W${win.week}. Lowest winning score on file.`,[win]);if(combined)add('Everybody ate.',`${year(combined.season)} W${combined.week}: ${F(combined.combined)} combined points, highest known meeting.`,[combined]);if(small)add('Everybody was apparently busy.',`${year(small.season)} W${small.week}: ${F(small.combined)} combined points, lowest known meeting.`,[small]);if(q.closeRace)add('A rounding error with an ego.',`${names(q.closeRace.a.franchise).displayName||names(q.closeRace.a.franchise).currentName} and ${names(q.closeRace.b.franchise).displayName||names(q.closeRace.b.franchise).currentName} are ${F(q.closeRace.gap)} points apart in the imported scoring archive.`,[...q.closeRace.a.scoreEvidence,...q.closeRace.b.scoreEvidence]);for(const r of q.changes.slice(0,1))add('A season-to-season plot twist.',`${names(r.franchise).displayName||names(r.franchise).currentName}: ${sign(r.change)} PPG between ${year(r.before.season)} and ${year(r.after.season)}. ${r.partial?'Provisional incomplete-season comparison.':''}`,[...r.before.evidence,...r.after.evidence]);const crown=sorted(q.belt.crowns.filter(c=>c.highs),'highs')[0];if(crown)add('The weekly crown collection.',`${names(crown.franchise).displayName||names(crown.franchise).currentName} has ${crown.highs} weekly high${crown.highs===1?'':'s'} in ${crown.active} complete active weeks (${P(crown.highs/crown.active)}). Tied leaders share credit.`,crown.highEvidence);const biggest=q.orientedPairs.sort((a,b)=>b.diff-a.diff)[0];if(biggest)add('The biggest known grudge ledger.',`${names(biggest.franchise).displayName||names(biggest.franchise).currentName} is ${sign(biggest.diff)} points against ${names(biggest.opponent).displayName||names(biggest.opponent).currentName} across ${biggest.games} known meetings.`,biggest.meetings);
 for(const f of engine.data.franchises){const above=q.seasonRows.filter(s=>s.franchise===f.id&&s.relative>0),below=q.seasonRows.filter(s=>s.franchise===f.id&&s.relative<0);if(above.length)add('Above the room’s average.',`${f.displayName||f.currentName} exceeded observed league PPG in ${above.length} supplied season${above.length===1?'':'s'}. Partial years count only as provisional observations.`,above.flatMap(s=>s.evidence));if(below.length)add('Below the room’s average.',`${f.displayName||f.currentName} fell below observed league PPG in ${below.length} supplied season${below.length===1?'':'s'}.`,below.flatMap(s=>s.evidence));}
}
function renderFacts(){if(!facts.length){$('#fact-stories').innerHTML=pending('The story desk needs source data in this range.');return;}const selected=Array.from({length:Math.min(6,facts.length)},(_,i)=>facts[(rot+i)%facts.length]);$('#fact-stories').innerHTML=selected.map(f=>`<article class="fact-story"><span>THE WADD / DATA-DERIVED DISPATCH</span><h3>${E(f.title)}</h3><p>${E(f.text)}</p>${receipt('RECEIPTS ↗',f.title,f.rows)}</article>`).join('');}
 function renderRecordBook(){const needle=$('#record-search').value.toLowerCase(),category=$('#record-category').value,rs=records.filter(r=>(category==='ALL'||r.category===category)&&`${r.label} ${r.owner.replace(/<[^>]*>/g,'')} ${r.detail} ${r.value}`.toLowerCase().includes(needle));$('#record-results').innerHTML=`<p class="record-results">${rs.length} supported record${rs.length===1?'':'s'} · ${E(selectedLabel())}</p>${table(['CATEGORY','RECORD','HOLDER','VALUE','RECEIPTS'],rs.map(r=>[E(r.category),E(r.label),r.owner,E(r.value),receipt('OPEN FILE ↗',r.label,r.evidence,`<p>${r.owner}: ${E(r.value)}.</p><p>${E(r.detail)}</p>`)]))}`;}
async function init(){const response=await fetch('../data/history/archive.json');if(!response.ok)throw Error('Archive could not be loaded');engine=H.createEngine(await response.json());$('#edition-coverage').textContent=engine.coverage.scoring;$('#coverage').innerHTML=`SCORING ARCHIVE: ${E(engine.coverage.scoring)}<br>DETAILED MATCHUPS: ${E(engine.coverage.matchups)}<br>CHAMPIONSHIPS: ${E(engine.coverage.championships)}`;$('#data-notice').innerHTML='<b>THE CANONICAL HISTORY IS ON FILE.</b><br>'+coverageGaps().map(E).join('<br>')+'<br><a href="../data/history/archive.json">READ THE CURRENT SOURCE ARCHIVE ↗</a>';
 $('.filter-scroll').innerHTML=[['all','ALL HISTORY'],['since2020','SINCE 2020'],['since2021','2021–PRESENT'],...Array.from({length:6},(_,i)=>[String(2021+i),2021+i===2026?'2026 YTD':String(2021+i)])].map(([value,label])=>`<button data-range="${value}" aria-pressed="${value===range}">${label}</button>`).join('');render();
 $('#methodology').onclick=methodology;$('#print').onclick=()=>window.print();$('#close-dialog').onclick=()=>$('#receipt-dialog').close();$('#receipt-dialog').addEventListener('close',()=>document.body.classList.remove('receipt-print'));$('#receipt-dialog').addEventListener('click',e=>{if(e.target===$('#receipt-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});$('#print-receipt').onclick=()=>{document.body.classList.add('receipt-print');window.print();};window.addEventListener('afterprint',()=>document.body.classList.remove('receipt-print'));
 $('#copy-receipt').onclick=async()=>{const u=new URL(location.href);u.searchParams.set('range',range);u.searchParams.set('scope',scope);u.hash=lastReceipt?.token?encodeURIComponent(lastReceipt.token):'record-book';try{await navigator.clipboard.writeText(u.href);$('#copy-status').textContent='Receipt link copied.';}catch{$('#copy-status').textContent=u.href;}};
 $('#game-scope').onchange=()=>{scope=$('#game-scope').value;render();};
 document.addEventListener('click',e=>{let actionElement=e.target.closest('[data-action]');if(actionElement){actions.get(actionElement.dataset.action)?.();return;}let r=e.target.closest('[data-range]');if(r){range=r.dataset.range;document.querySelectorAll('[data-range]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.range===range));render();return;}let race=e.target.closest('[data-race]');if(race){raceRange=race.dataset.race;document.querySelectorAll('[data-race]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.race===raceRange));drawRace();return;}let trend=e.target.closest('[data-ppg]');if(trend){ppgRange=trend.dataset.ppg;document.querySelectorAll('[data-ppg]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.ppg===ppgRange));drawYears();return;}let toggle=e.target.closest('[data-toggle-team]');if(toggle){let id=toggle.dataset.toggleTeam;hidden.has(id)?hidden.delete(id):hidden.add(id);drawYears();drawRace();return;}let weekly=e.target.closest('[data-weeks]');if(weekly){document.querySelectorAll('[data-weeks]').forEach(b=>b.setAttribute('aria-pressed',b===weekly));$('#weekly-table').innerHTML=table(['RK','FRANCHISE','THEN KNOWN AS','WHEN','SCORE','OPPONENT','RESULT'],scoringRows(sorted(q.scores,'score',weekly.dataset.weeks==='high').slice(0,20)));return;}if(e.target.closest('#rotate-facts')){rot=(rot+6)%Math.max(facts.length,1);renderFacts();}});
 document.addEventListener('keydown',e=>{if(e.target.matches('circle[data-action]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();actions.get(e.target.dataset.action)?.();}});
 const chartTip=e=>{let p=e.target.closest('[data-chart-tip]');if(p)p.closest('.chart-stage').querySelector('.chart-tooltip').textContent=p.dataset.chartTip;};document.addEventListener('pointerover',chartTip);document.addEventListener('focusin',chartTip);
 document.addEventListener('input',e=>{if(e.target.id==='record-search')renderRecordBook();});document.addEventListener('change',e=>{let id=e.target.id;if(id==='victim-franchise')$('#victim-file').innerHTML=personality(e.target.value);if(id==='record-category')renderRecordBook();if(id==='machine-year'||id==='machine-franchise')$('#machine-paper').innerHTML=timeMachine($('#machine-year').value,$('#machine-franchise').value);if(id==='tape-a'||id==='tape-b')$('#tape-paper').innerHTML=tape($('#tape-a').value,$('#tape-b').value);});
 const url=new URL(location.href);if(['all','since2020','since2021','2021','2022','2023','2024','2025','2026'].includes(url.searchParams.get('range'))){range=url.searchParams.get('range');document.querySelectorAll('[data-range]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.range===range));}if(['all','regular'].includes(url.searchParams.get('scope'))){scope=url.searchParams.get('scope');$('#game-scope').value=scope;}if(url.searchParams.has('range')||url.searchParams.has('scope'))render();const token=decodeURIComponent(location.hash.slice(1));if(token.startsWith('row:')){const row=[...engine.data.scores,...engine.data.games,...engine.data.championships].find(r=>r.id===token.slice(4));if(row)showReceipt('SHARED EVIDENCE RECEIPT','<p>The original source row is reproduced below.</p>',[row],token);}if(token.startsWith('rivalry:')){const [,a,b]=token.split(':');if(names(a)&&names(b))rivalryFile(a,b);}if(token.startsWith('profile:')){const id=token.slice(8);if(names(id))profileFile(id);}
 }
